const n19=outputParser({type:"@n8n/n8n-nodes-langchain.outputParserStructured",version:1.3,config:{"name":"Storyboard JSON Parser","parameters":{"schemaType":"manual","inputSchema":"{\"type\": \"object\", \"properties\": {\"scenes\": {\"type\": \"array\", \"minItems\": 1, \"maxItems\": 5, \"items\": {\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"string\"}, \"title\": {\"type\": \"string\"}, \"narration\": {\"type\": \"string\"}, \"timestamp\": {\"type\": \"string\"}, \"whatHappening\": {\"type\": \"string\"}, \"background\": {\"type\": \"string\"}, \"handDrawnElements\": {\"type\": \"string\"}, \"onScreenText\": {\"type\": \"string\"}, \"transitionsMotion\": {\"type\": \"string\"}, \"visualFamily\": {\"type\": \"string\"}, \"visualBeat\": {\"type\": \"string\"}, \"styleNotes\": {\"type\": \"string\"}, \"imagePrompt\": {\"type\": \"string\"}, \"characterPresent\": {\"type\": \"boolean\"}}, \"required\": [\"id\", \"title\", \"narration\", \"timestamp\", \"whatHappening\", \"background\", \"handDrawnElements\", \"onScreenText\", \"transitionsMotion\", \"visualFamily\", \"visualBeat\", \"styleNotes\", \"imagePrompt\", \"characterPresent\"], \"additionalProperties\": false}}}, \"required\": [\"scenes\"], \"additionalProperties\": false}","autoFix":false}},output:[{"ok": true, "requestId": "story-demo-reference-test", "request_id": "story-demo-reference-test", "status": "queued", "result_json": "{}", "error_json": "", "updated_at": "", "fileId": "reference-id", "planPrompt": "Plan one scene", "scene": {"id": "scene-01"}, "query": {"requestId": "story-demo-reference-test", "sceneId": "scene-01"}, "body": {"script": "Narration"}, "feedback_key": "review-key", "rating": "up", "comment": "", "scene_id": "scene-01", "scene_title": "Scene", "narration": "Narration", "image_prompt": "Draw one scene", "submitted_at": "", "canGenerate": true, "statusCode": 200}]});
const n20=tool({type:"@n8n/n8n-nodes-langchain.toolCode",version:1.3,config:{"name":"Fred Style Reference Search","parameters":{"description":"Search Fred\u2019s approved storyboard visual brief for host, environment, anatomy, metaphor, and composition guidance. Call this before drafting image prompts; it returns style notes only and never generates images.","jsCode":"const previousBrief = (() => {\nconst queryText=String(query??\"\").toLowerCase();\nconst tokens=Array.from(new Set(queryText.match(/[a-z0-9_]+/g)??[]));\nconst chunks=[\n{id:\"shared_ink_and_character\",family:\"shared\",tags:[\"host\",\"character\",\"face\",\"glasses\",\"head\",\"outline\",\"ink\",\"professor\",\"fred\"],text:\"Shared drawing language: bold, slightly irregular hand-drawn black contours; simplified readable forms; minimal face marks; solid fills; clear silhouettes. Preserve the approved professor/host's pale cream oval head, face spacing, glasses and dark clothing when that host appears.\"},\n{id:\"global_composition\",family:\"shared\",tags:[\"composition\",\"widescreen\",\"text\",\"caption\",\"logo\",\"watermark\",\"motion\",\"transition\"],text:\"CSV contract: timestamp, narration, background, hand-drawn characters/props, on-screen text and transitions/motion are distinct fields. The still uses one narration-grounded moment with its setting and props. Timecodes and edit cues are metadata, not things to draw. Use the requested aspect ratio (default 16:9), central safe area, one focal point; no text, logos, watermarks, UI or borders.\"},\n{id:\"topic_menu\",family:\"topic_menu\",tags:[\"topic_menu\",\"menu\",\"intro\",\"grid\",\"icons\",\"circles\",\"overview\",\"topics\"],text:\"Topic menu: white/light field, circular topic illustrations in a grid, high-contrast headline and short labels in final edit. Generate icons and leave clean space; labels remain overlay metadata.\"},\n{id:\"character_environment\",family:\"character_environment\",tags:[\"character_environment\",\"character\",\"host\",\"room\",\"living\",\"cafe\",\"bar\",\"office\",\"street\",\"setting\",\"background\",\"shelf\",\"plant\",\"kitchen\",\"phone\",\"pocket\"],text:\"Character environment: one readable action in a specified living room, cafe, bar, kitchen, office, city or street. Use listed props only. Warm cream, yellow/ochre, amber, brown, muted green and charcoal recur; daylight may introduce blue. Layered settings can have furniture, shelves, windows, plants and lamps.\"},\n{id:\"host_lecture\",family:\"host_lecture\",tags:[\"host_lecture\",\"professor\",\"lecture\",\"chalkboard\",\"teaching\",\"pointer\"],text:\"Host lecture: approved professor presents one idea beside a chalkboard, simple diagram or yellow teaching background. Preserve host identity; do not render board lettering.\"},\n{id:\"anatomy_insert\",family:\"anatomy_insert\",tags:[\"anatomy_insert\",\"anatomy\",\"organ\",\"liver\",\"heart\",\"body\",\"health\",\"nerve\",\"brain\",\"vessel\",\"blood\",\"cell\",\"fainting\"],text:\"Anatomy insert: relevant organ/body mechanism as focal point; simplified recognizable educational drawing, thick ink contours, warm coral/orange/brown and muted yellow. Keep accurate to narration and non-graphic; no invented labels or diagnoses.\"},\n{id:\"concept_metaphor\",family:\"concept_metaphor\",tags:[\"concept_metaphor\",\"metaphor\",\"analogy\",\"mechanism\",\"phone\",\"vibration\",\"brain\",\"prediction\",\"wheel\"],text:\"Concept metaphor: one concrete, legible analogy grounded in the script. Keep it visibly illustrative and do not imply unsupported medical facts.\"},\n{id:\"diagram_comparison\",family:\"diagram_comparison\",tags:[\"diagram_comparison\",\"diagram\",\"compare\",\"split\",\"screen\",\"nerve\",\"pressure\",\"signal\",\"vessel\",\"temperature\",\"fever\",\"virus\",\"bacteria\"],text:\"Diagram/comparison: simple body/nerve diagram, split screen, comparison or highlighted region only when the storyboard requests it. Exact labels remain separate overlay metadata.\"},\n{id:\"single_action_vignette\",family:\"single_action_vignette\",tags:[\"single_action_vignette\",\"action\",\"man\",\"woman\",\"touch\",\"pull\",\"sneeze\",\"cough\",\"faint\",\"walk\",\"sit\",\"stand\",\"pain\",\"stove\"],text:\"Single action: one frozen readable pose with few props. Do not combine before/after states or multiple cuts in one frame.\"},\n{id:\"csv_phantom_example\",family:\"character_environment\",tags:[\"phantom\",\"vibration\",\"phone\",\"pocket\",\"notification\"],text:\"CSV example, Every Weird Body Glitch scene 2 (00:01-00:11): bald green-shirt man feels leg buzz and checks phone; yellow-wall living room with green couch, plant and landscape art; grey smartphone; no overlay text; hard-cut/zoom notes are editing metadata.\"},\n{id:\"csv_split_example\",family:\"diagram_comparison\",tags:[\"phantom\",\"vibration\",\"split\",\"three\",\"people\",\"phone\"],text:\"CSV example, Every Weird Body Glitch scene 3 (00:11-00:16): three people check phones in split screen across gray city, yellow/green living room and white kitchen; overlay 'Phantom Vibration Syndrome'; hard cut/text fade are metadata.\"},\n{id:\"csv_brain_wheel_example\",family:\"concept_metaphor\",tags:[\"phantom\",\"vibration\",\"brain\",\"wheel\",\"hamster\",\"phone\"],text:\"CSV example, Every Weird Body Glitch scene 7 (00:57-01:06): professor lectures while a brain runs on a hamster wheel inside a cutaway head; chalkboard then yellow wall; hard cut/wheel spin are editing metadata. Split the actions if more than one still is needed.\"},\n{id:\"csv_pins_example\",family:\"single_action_vignette\",tags:[\"pins\",\"needles\",\"foot\",\"static\",\"numb\",\"sitting\"],text:\"CSV example, Every Weird Body Glitch scene 9 (01:08-01:18): green-shirt man sits awkwardly and the foot becomes a static block; living-room couch. Choose one frozen moment.\"},\n{id:\"csv_nerve_example\",family:\"diagram_comparison\",tags:[\"pins\",\"needles\",\"nerve\",\"pressure\",\"blood\",\"vessel\",\"foot\",\"tingling\"],text:\"CSV example, Every Weird Body Glitch scene 11 (01:22-01:59) contains several cuts: compressed nerve/vessel, pressure lifting, pins/needles and character reaction. Yellow/blue fields, foot/rope/cross-section/nerve/vessel/pins. Split into beats; keep labels/arrows/rain as metadata/cues.\"},\n{id:\"csv_stove_example\",family:\"single_action_vignette\",tags:[\"pain\",\"fever\",\"stove\",\"hand\",\"kitchen\",\"pull\",\"touch\"],text:\"CSV example, Strangest Things Your Body Does scene 7 (00:26-00:34): man touches a white stove in a kitchen; freeze the hand-pulling-away moment; no overlay text.\"},\n{id:\"csv_fever_example\",family:\"diagram_comparison\",tags:[\"fever\",\"temperature\",\"pathogen\",\"bacteria\",\"virus\",\"immune\",\"yellow\"],text:\"CSV example, Strangest Things Your Body Does scene 23 (01:48-01:53): yellow infographic field with bacteria and virus diagrams; exact labels remain metadata.\"},\n{id:\"csv_fainting_example\",family:\"anatomy_insert\",tags:[\"fainting\",\"syncope\",\"blood\",\"brain\",\"vessel\",\"oxygen\"],text:\"CSV example, Strangest Things Your Body Does scene 105 (09:18-09:27): yellow background with head/brain/vessels for blood flow; 'Fainting (Syncope)' is overlay metadata.\"}\n];\nconst ranked=chunks.map(chunk=>({chunk,score:tokens.reduce((n,t)=>n+(chunk.tags.some(tag=>tag===t||tag.includes(t)||t.includes(tag))?2:0),0)+(queryText.includes(chunk.family)?6:0)}));\nconst selected=ranked.filter(x=>x.chunk.family===\"shared\").map(x=>x.chunk);\nconst matches=ranked.filter(x=>x.chunk.family!==\"shared\").sort((a,b)=>b.score-a.score).filter(x=>x.score>0).slice(0,3).map(x=>x.chunk);\nselected.push(...matches);\nif(!matches.length)selected.push(chunks.find(x=>x.id===\"character_environment\"));\nreturn \"Retrieved from fred-style-v2-csv. These are text rules and selected CSV examples, not Drive image files. Apply only relevant families; preserve timing, overlays, and editor cues separately.\\\\n\\\\n\"+selected.map(c=>\"[\"+c.id+\" | \"+c.family+\"]\\\\n\"+c.text).join(\"\\\\n\\\\n\");\n})();\nreturn \"FRED_VISUAL_ANCHORS_V3: actual approved Drive images override generic character assumptions. Casual character: brown skin, dark green shirt, oversized rounded head, white narrow eyes, tiny pupils, very thin black limbs. Background: yellow walls, green sofa, blue accents, rough black ink perspective, flat fills. Preserve the correct identity; the casual man is distinct from the cream-faced professor host.\\n\\n\" + previousBrief;"}},output:[{"ok": true, "requestId": "story-demo-reference-test", "request_id": "story-demo-reference-test", "status": "queued", "result_json": "{}", "error_json": "", "updated_at": "", "fileId": "reference-id", "planPrompt": "Plan one scene", "scene": {"id": "scene-01"}, "query": {"requestId": "story-demo-reference-test", "sceneId": "scene-01"}, "body": {"script": "Narration"}, "feedback_key": "review-key", "rating": "up", "comment": "", "scene_id": "scene-01", "scene_title": "Scene", "narration": "Narration", "image_prompt": "Draw one scene", "submitted_at": "", "canGenerate": true, "statusCode": 200}]});
