const n14=node({type:"n8n-nodes-base.code",version:2,config:{"name":"Prepare Visual Reference Context","parameters":{"mode":"runOnceForAllItems","jsCode":"const req = $('Normalize Request').first().json;\nconst files = $('Select Approved Reference Files').all();\nconst items = $input.all();\nif (items.length !== 2 || items.some(i=>!i.binary?.data)) throw new Error('Two approved reference image binaries are required. No image credits were used.');\nconst references = [];\nconst binary = {};\nfor (let index=0; index<items.length; index++) {\n  const buffer = await this.helpers.getBinaryDataBuffer(index,'data');\n  const meta = files[index].json;\n  const mimeType = items[index].binary.data.mimeType || 'image/png';\n  if (!mimeType.startsWith('image/')) throw new Error('A reference download was not an image.');\n  references.push({...meta,mimeType,dataUrl:'data:'+mimeType+';base64,'+buffer.toString('base64')});\n  binary['reference'+index] = items[index].binary.data;\n}\nconst job=JSON.parse(req.result_json); job.references=references; job.status='planning';\nreturn [{json:{request_id:req.requestId,status:'planning',result_json:JSON.stringify(job),error_json:'',updated_at:new Date().toISOString()}, binary}];"},"onError":"continueErrorOutput"},output:[{"ok": true, "requestId": "story-demo-reference-test", "request_id": "story-demo-reference-test", "status": "queued", "result_json": "{}", "error_json": "", "updated_at": "", "fileId": "reference-id", "planPrompt": "Plan one scene", "scene": {"id": "scene-01"}, "query": {"requestId": "story-demo-reference-test", "sceneId": "scene-01"}, "body": {"script": "Narration"}, "feedback_key": "review-key", "rating": "up", "comment": "", "scene_id": "scene-01", "scene_title": "Scene", "narration": "Narration", "image_prompt": "Draw one scene", "submitted_at": "", "canGenerate": true, "statusCode": 200}]});
