const n38=node({type:"n8n-nodes-base.code",version:2,config:{"name":"Prepare Flare Image Tool Call","parameters":{"mode":"runOnceForAllItems","jsCode":"const input=$('Flare Image Tool Input').first().json;\nif (!$json.result_json) throw new Error('Unknown storyboard job.');\nconst job=JSON.parse($json.result_json), scene=job.scenes.find(s=>s.id===input.sceneId);\nif (!scene) throw new Error('Unknown storyboard scene.');\nconst canGenerate=!scene.generationAttempted && scene.imageStatus!=='completed';\nif (!Array.isArray(job.references) || job.references.length!==2) throw new Error('Approved image references are missing.');\nif (canGenerate) { scene.generationAttempted=true; scene.imageStatus='generating'; scene.finalImagePrompt=String(input.imagePrompt || scene.imagePrompt).slice(0,8000); }\nreturn [{json:{canGenerate,sceneId:scene.id,request_id:$json.request_id,status:'generating',\nresult_json:JSON.stringify(job),error_json:'',updated_at:new Date().toISOString()}}];"}},output:[{"ok": true, "requestId": "story-demo-reference-test", "request_id": "story-demo-reference-test", "status": "queued", "result_json": "{}", "error_json": "", "updated_at": "", "fileId": "reference-id", "planPrompt": "Plan one scene", "scene": {"id": "scene-01"}, "query": {"requestId": "story-demo-reference-test", "sceneId": "scene-01"}, "body": {"script": "Narration"}, "feedback_key": "review-key", "rating": "up", "comment": "", "scene_id": "scene-01", "scene_title": "Scene", "narration": "Narration", "image_prompt": "Draw one scene", "submitted_at": "", "canGenerate": true, "statusCode": 200}]});
