const n43=node({type:"n8n-nodes-base.code",version:2,config:{"name":"Format Scene Result","parameters":{"mode":"runOnceForAllItems","jsCode":"const body=$json.body ?? $json;\nconst image=body.data?.[0];\nconst b64=image?.b64_json;\nconst mimeType=image?.media_type || body.media_type || 'image/png';\nif (b64) {\n const buffer=Buffer.from(b64,'base64');\n const extension=mimeType==='image/jpeg'?'jpg':'png';\n const sceneId=$('Flare Image Tool Input').first().json.sceneId;\n const data=await this.helpers.prepareBinaryData(buffer,sceneId+'.'+extension,mimeType);\n return [{json:{imageStatus:'completed',imageData:'data:'+mimeType+';base64,'+b64,mimeType,costUsd:body.usage?.cost ?? null,\nreferenceCount:2,model:'openai/gpt-image-2.5-flare'},binary:{data}}];\n}\nconst providerError=body.error;\nconst message=typeof providerError==='string'?providerError:providerError?.message || body.message || 'The image provider did not return image bytes.';\nreturn [{json:{imageStatus:'failed',error:String(message).slice(0,1500),referenceCount:2,model:'openai/gpt-image-2.5-flare'}}];"}},output:[{"ok": true, "requestId": "story-demo-reference-test", "request_id": "story-demo-reference-test", "status": "queued", "result_json": "{}", "error_json": "", "updated_at": "", "fileId": "reference-id", "planPrompt": "Plan one scene", "scene": {"id": "scene-01"}, "query": {"requestId": "story-demo-reference-test", "sceneId": "scene-01"}, "body": {"script": "Narration"}, "feedback_key": "review-key", "rating": "up", "comment": "", "scene_id": "scene-01", "scene_title": "Scene", "narration": "Narration", "image_prompt": "Draw one scene", "submitted_at": "", "canGenerate": true, "statusCode": 200}]});
