const n70=node({type:"n8n-nodes-base.code",version:2,config:{"name":"Create Fred Storyboard CSV","parameters":{"mode":"runOnceForAllItems","jsCode":"const job=JSON.parse($json.result_json || '{}');\nif (!Array.isArray(job.scenes) || !job.scenes.length) return [{json:{ok:false,statusCode:409,error:'The scene plan is not available yet.'}}];\nconst columns=[['Scene','sceneNumber'],['Timestamp','timestamp'],['Voiceover','narration'],[\"What's happening\",'whatHappening'],\n['Background','background'],['Hand-drawn characters & props','handDrawnElements'],['On-screen text','onScreenText'],['Transitions/Motion','transitionsMotion']];\nconst cell=value=>{\n let text=String(value ?? '');\n if (/^[\\s\\u0000-\\u001f]*[=+@-]/.test(text)) text=\"'\"+text;\n return '\"'+text.replace(/\"/g,'\"\"')+'\"';\n};\nconst rows=[columns.map(([label])=>label),...job.scenes.map(scene=>columns.map(([,key])=>scene[key] ?? ''))];\nconst csv='\\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\\r\\n')+'\\r\\n';\nconst file=await this.helpers.prepareBinaryData(Buffer.from(csv,'utf8'),'fred-storyboard-'+job.requestId+'.csv','text/csv');\nreturn [{json:{ok:true},binary:{data:file}}];"}},output:[{"ok": true, "requestId": "story-demo-reference-test", "request_id": "story-demo-reference-test", "status": "queued", "result_json": "{}", "error_json": "", "updated_at": "", "fileId": "reference-id", "planPrompt": "Plan one scene", "scene": {"id": "scene-01"}, "query": {"requestId": "story-demo-reference-test", "sceneId": "scene-01"}, "body": {"script": "Narration"}, "feedback_key": "review-key", "rating": "up", "comment": "", "scene_id": "scene-01", "scene_title": "Scene", "narration": "Narration", "image_prompt": "Draw one scene", "submitted_at": "", "canGenerate": true, "statusCode": 200}]});
